public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n + 1];
    List<Integer>[] graph = new List[n + 1];

    for (int i = 0; i <= n; i++) {
        graph[i] = new ArrayList<>();
    }

    for (int[] path : paths) {
        graph[path[0]].add(path[1]);
        graph[path[1]].add(path[0]);
    }

    if (dfs(graph, visited, start[0], end[0])) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

private static boolean dfs(List<Integer>[] graph, boolean[] visited, int current, int target) {
    if (current == target) {
        return true;
    }

    visited[current] = true;

    for (int neighbor : graph[current]) {
        if (!visited[neighbor]) {
            if (dfs(graph, visited, neighbor, target)) {
                return true;
            }
        }
    }

    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n < 2 || start.length != 2 || end.length != 2 || paths == null) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Build the adjacency list for the maze
    Map<Integer, List<Integer>> adjacencyList = new HashMap<>();
    for (int[] path : paths) {
        int from = path[0];
        int to = path[1];
        adjacencyList.computeIfAbsent(from, k -> new ArrayList<>()).add(to);
        adjacencyList.computeIfAbsent(to, k -> new ArrayList<>()).add(from);
    }

    // Perform a depth-first search to check if there is a path from start to end
    Set<Integer> visited = new HashSet<>();
    if (!dfs(adjacencyList, start[0], end[0], visited)) {
        return "cannot be travelled";
    }

    return "can be travelled";
}

private static boolean dfs(Map<Integer, List<Integer>> adjacencyList, int current, int target, Set<Integer> visited) {
    // If the current node is the target, return true
    if (current == target) {
        return true;
    }

    // Mark the current node as visited
    visited.add(current);

    // Explore all adjacent nodes
    for (int neighbor : adjacencyList.getOrDefault(current, Collections.emptyList())) {
        if (!visited.contains(neighbor)) {
            if (dfs(adjacencyList, neighbor, target, visited)) {
                return true;
            }
        }
    }

    // Unmark the current node as visited
    visited.remove(current);
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    Set<String> visited = new HashSet<>();
    Map<String, List<int[]>> graph = new HashMap<>();

    for (int[] path : paths) {
        String from = path[0] + "," + path[1];
        String to = path[2] + "," + path[3];
        graph.putIfAbsent(from, new ArrayList<>());
        graph.putIfAbsent(to, new ArrayList<>());
        graph.get(from).add(new int[]{path[2], path[3]});
        graph.get(to).add(new int[]{path[0], path[1]});
    }

    Stack<int[]> stack = new Stack<>();
    stack.push(start);

    while (!stack.isEmpty()) {
        int[] current = stack.pop();
        String key = current[0] + "," + current[1];

        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        if (!visited.contains(key)) {
            visited.add(key);
            for (int[] neighbor : graph.get(key)) {
                stack.push(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n*n];
    visited[start[0]*n + start[1]] = true;
    return canTravelMazeRecursive(start, end, paths, visited, n) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravelMazeRecursive(int[] current, int[] end, int[][] paths, boolean[] visited, int n) {
    if (current[0] == end[0] && current[1] == end[1]) {
        return true;
    }
    for (int[] path : paths) {
        if ((path[0] == current[0] && path[1] == current[1] && !visited[path[2]*n + path[3]]) ||
            (path[0] == current[2] && path[1] == current[3] && !visited[path[2]*n + path[3]])) {
            visited[path[2]*n + path[3]] = true;
            if (canTravelMazeRecursive(new int[]{path[2], path[3]}, end, paths, visited, n)) {
                return true;
            }
            visited[path[2]*n + path[3]] = false;
        }
    }
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    Set<Integer> visited = new HashSet<>();
    return dfs(start[0], start[1], end[0], end[1], paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int x, int y, int ex, int ey, int[][] paths, Set<Integer> visited) {
    if (x < 0 || x >= paths.length || y < 0 || y >= paths[0].length || visited.contains(x * paths.length + y)) {
        return false;
    }
    visited.add(x * paths.length + y);
    if (x == ex && y == ey) {
        return true;
    }
    for (int[] path : paths) {
        if (path[0] == x && path[1] == y) {
            boolean result = dfs(path[2], path[3], ex, ey, paths, visited) || dfs(path[3], path[2], ex, ey, paths, visited);
            visited.remove(x * paths.length + y);
            return result;
        }
    }
    visited.remove(x * paths.length + y);
    return false;
}

public static String appx(String word1, String word2) {
    Set<Character> set1 = new HashSet<>();
    for (char c : word1.toCharArray()) {
        set1.add(c);
    }

    int commonLetters = 0;
    for (char c : word2.toCharArray()) {
        if (set1.contains(c)) {
            commonLetters++;
            set1.remove(c);
        }
    }

    int numerator = commonLetters;
    int denominator = word1.length() + word2.length() - commonLetters;

    // Simplify the fraction
    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;

    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

