public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        return "appx(null, null) = 0";
    }

    word1 = word1.toLowerCase();
    word2 = word2.toLowerCase();
    boolean[] seen = new boolean[word2.length()];
    int common = 0;

    for (char c : word1.toCharArray()) {
        for (int i = 0; i < word2.length(); i++) {
            if (word2.charAt(i) == c && !seen[i]) {
                seen[i] = true;
                common++;
                break;
            }
        }
    }

    int sum = word1.length() + word2.length() - common;
    return "appx(" + word1 + ", " + word2 + ") = " + common + "/" + sum;
}

public static String appx(String word1, String word2) {
