    Set<Character> set2 = new HashSet<>();

    for (char c : word1.toCharArray()) {
        set1.add(c);
    }

    for (char c : word2.toCharArray()) {
        set2.add(c);
    }

    int commonLetters = set1.size() + set2.size() - (set1.size() + set2.size() - (set1.size() & set2.size()));

    int numerator = commonLetters;
    int denominator = word1.length() + word2.length();

    int gcd = gcd(numerator, denominator);

    return "appx(" + word1 + ", " + word2 + ") = " + (numerator / gcd) + "/" + (denominator / gcd);
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

public static String appx(String word1, String word2) {
        int commonLetters = 0;
        Set<Character> lettersInWord1 = new HashSet<>();

        for (char c : word1.toCharArray()) {
            lettersInWord1.add(c);
        }

        for (char c : word2.toCharArray()) {
            if (lettersInWord1.contains(c)) {
                commonLetters++;
                lettersInWord1.remove(c); // Ensure each common letter is counted only once
            }
        }

        int totalLetters = word1.length() + word2.length();

        // Reduce the fraction
        BigInteger numerator = BigInteger.valueOf(commonLetters);
        BigInteger denominator = BigInteger.valueOf(totalLetters);
        BigInteger gcd = numerator.gcd(denominator);

        numerator = numerator.dividedBy(gcd);
        denominator = denominator.dividedBy(gcd);

        return String.format("approx(%s, %s) = %d/%d", word1, word2, numerator, denominator);
    }

