public boolean canArrange(int[] arr, int k) {
    int[] remainderCounts = new int[k];
    for (int num : arr) {
        int remainder = ((num % k) + k) % k; // Ensure non-negative remainder
        remainderCounts[remainder]++;
    }

    if (remainderCounts[0] % 2 != 0) {
        return false; // If there's an odd count of elements with remainder 0, it's not possible
    }

    for (int i = 1; i <= k / 2; i++) {
        if (remainderCounts[i] != remainderCounts[k - i]) {
            return false; // If counts of elements with remainder i and k-i are not equal, it's not possible
        }
    }

    return true;
}

