public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }

    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }

    boolean[] visited = new boolean[n];
    return dfs(graph, visited, 0, hasApple) * 2;
}

private int dfs(List<List<Integer>> graph, boolean[] visited, int node, boolean[] hasApple) {
    visited[node] = true;
    int time = 0;

    for (int neighbor : graph.get(node)) {
        if (!visited[neighbor]) {
            time += dfs(graph, visited, neighbor, hasApple);
        }
    }

    if (node != 0 && (time > 0 || hasApple[node])) {
        return time + 1;
    }

    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n == 0) {
        return 0;
    }

    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }

    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }

    return dfs(0, -1, graph, hasApple);
}

private int dfs(int node, int parent, List<List<Integer>> graph, boolean[] hasApple) {
    int time = 0;
    for (int neighbor : graph.get(node)) {
        if (neighbor == parent) {
            continue;
        }
        int neighborTime = dfs(neighbor, node, graph, hasApple);
        if (neighborTime > 0 || hasApple[neighbor]) {
            time += 2 + neighborTime;
        }
    }
    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Create an adjacency list to represent the tree
    List<Integer>[] tree = new List[n];
    for (int i = 0; i < n; i++) {
        tree[i] = new ArrayList<>();
    }

    // Build the tree from the edges
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        tree[u].add(v);
        tree[v].add(u);
    }

    // Use DFS to calculate the minimum time required to collect all apples
    return dfs(0, -1, tree, hasApple) * 2;
}

private int dfs(int node, int parent, List<Integer>[] tree, boolean[] hasApple) {
    int time = 0;

    // Traverse all neighboring nodes
    for (int neighbor : tree[node]) {
        if (neighbor == parent) {
            continue; // Skip the parent node to avoid cycles
        }

        // Recursively calculate the time for the neighbor
        int childTime = dfs(neighbor, node, tree, hasApple);

        // If the neighbor has an apple or its subtree has apples, add the time
        if (hasApple[neighbor] || childTime > 0) {
            time += childTime + 2; // +2 to account for the time to move to and from the neighbor
        }
    }

    return time;
}

