public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;

    int sum = Arrays.stream(nums).sum();
    if (sum == 0) return true;

    Map<Integer, Set<Integer>> dp = new HashMap<>();
    for (int i = 1; i <= n / 2; i++) {
        dp.put(i, new HashSet<>());
    }

    dp.get(0).add(0);

    for (int num : nums) {
        for (int i = n / 2; i >= 1; i--) {
            for (int s : dp.get(i - 1)) {
                int newSum = s + num;
                if (newSum * n == sum * i) {
                    return true;
                }
                dp.get(i).add(newSum);
            }
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }

    double sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][] dp = new boolean[n + 1][n + 1];
    dp[0][0] = true;

    for (int i = 1; i <= n; i++) {
        dp[i][0] = true;
    }

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            dp[j][i] = dp[j][i - 1];
            if (j <= i) {
                dp[j][i] |= dp[j - 1][i - 1] && nums[i - 1] * j == (int)(sum * j / n);
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (dp[i][n] && (int)(sum * i / n) == 0) {
            return true;
        }
    }

    return false;
}

