public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;

    long totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    boolean[] possibleAverages = new boolean[(n + 1) / 2];

    for (int i = 1; i < Math.min(n, 2048); i++) {
        Set<Long> sums = new HashSet<>();
        sums.add(0L);

        for (int num : nums) {
            Set<Long> newSums = new HashSet<>();
            for (long sum : sums) {
                newSums.add(sum + num);
            }
            sums.addAll(newSums);
        }

        for (long sum : sums) {
            if (sum != 0 && totalSum * i % n == sum * n) {
                possibleAverages[i] = true;
            }
        }
    }

    for (int i = 1; i < n / 2; i++) {
        if (possibleAverages[i] && possibleAverages[n - i]) {
            return true;
        }
    }

    return possibleAverages[n / 2];
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }

    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    for (int i = 1; i <= n / 2; i++) {
        if (totalSum * i % n == 0) {
            if (hasSubsetWithSum(nums, i, totalSum * i / n)) {
                return true;
            }
        }
    }

    return false;
}

private boolean hasSubsetWithSum(int[] nums, int targetSize, int targetSum) {
    int n = nums.length;
    boolean[][] dp = new boolean[targetSize + 1][targetSum + 1];

    for (int i = 0; i <= n; i++) {
        dp[i][0] = true;
    }

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= targetSum; j++) {
            if (nums[i - 1] > j) {
                dp[i][j] = dp[i - 1][j];
            } else {
                dp[i][j] = dp[i - 1][j] || dp[i - 1][j - nums[i - 1]];
            }
        }
    }

    return dp[n][targetSum];
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

