public static boolean hasAllCodes(String s, int k) {
        // If s's length is less than 2^k, it's impossible to have all binary strings of length k
        if (s.length() < Math.pow(2, k)) {
            return false;
        }

        // Use a HashSet to store unique substrings of length k
        HashSet<String> substrings = new HashSet<>();

        // Extract all substrings of length k from s
        for (int i = 0; i <= s.length() - k; i++) {
            substrings.add(s.substring(i, i + k));
        }

        // Check if the number of unique substrings is 2^k
        return substrings.size() == (1 << k);
    }

public boolean hasAllCodes(String s, int k) {
    if (s.length() < Math.pow(2, k)) {
        return false;
    }

    HashSet<String> seen = new HashSet<>();
    int totalCombinations = 1 << k;

    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);
        seen.add(substring);

        if (seen.size() == totalCombinations) {
            return true;
        }
    }

    return false;
}

