public int minInsertions(String s) {
    int count = 0;
    int insertions = 0;
    boolean needsClosing = false;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        if (c == '(') {
            if (needsClosing) {
                insertions++;
                needsClosing = false;
            }
            count++;
        } else if (c == ')') {
            if (count == 0) {
                insertions++;
            } else {
                count--;
            }
            needsClosing = true;
        }
    }

    if (count > 0) {
        insertions += count * 2;
        if (needsClosing) {
            insertions++;
        }
    }

    return insertions;
}

public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            balance++;
        } else {
            if (balance > 0) {
                balance--;
            } else {
                insertions++;
            }
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next character as it is already considered
            } else {
                insertions++; // Insert a closing parenthesis
            }
        }
    }

    insertions += balance * 2; // Each unmatched '(' needs a closing ')'

    return insertions;
}

public int minInsertions(String s) {
    int balance = 0; // Tracks the balance between '(' and ')'
    int insertions = 0; // Counts the number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        if (c == '(') {
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                // If it's "()", move to the next character
                i++;
            } else {
                // If it's ")", we need to insert a '(' to balance it
                insertions++;
            }
            balance++;
        } else if (c == ')') {
            balance--;
            if (balance < 0) {
                // If the balance goes negative, we need to insert a '(' to balance it
                insertions++;
                balance = 0;
            }
        }
    }

    // If balance is still positive, we need to insert ')' to balance it
    insertions += balance * 2;

    return insertions;
}

public int minInsertions(String s) {
    int insertions = 0;
    int balance = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        if (c == '(') {
            balance++;
        } else {
            if (balance == 0) {
                insertions++;
            } else {
                balance--;
            }

            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++;
            } else {
                insertions++;
            }
        }
    }

    return insertions + 2 * balance;
}

public int minInsertions(String s) {
    int leftBalance = 0;
    int rightBalance = 0;
    int insertions = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (rightBalance % 2 != 0) {
                insertions++;
                rightBalance--;
            }
            leftBalance++;
        } else {
            rightBalance++;
            if (rightBalance % 2 == 0 && leftBalance > 0) {
                leftBalance--;
            } else {
                insertions++;
            }
        }
    }

    insertions += leftBalance + rightBalance / 2;
    return insertions;
}

public int minOperations(int n) {
    int target = n;
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int sum = 0;
    for (int value : arr) {
        sum += value;
    }
    return (sum - (n * target)) / 2;
}

public int minOperations(int n) {
    int target = n;
    int totalOperations = 0;

    for (int i = 0; i < n / 2; i++) {
        totalOperations += target - (2 * i + 1);
    }

    return totalOperations;
}

public int minOperations(int n) {
    int target = n * n / 2;
    int sum = 0;
    for (int i = 0; i < n / 2; i++) {
        sum += (2 * i + 1);
    }
    return (target - sum);
}

public int minOperations(int n) {
    int target = n;
    int operations = 0;
    for (int i = 0; i < n; i++) {
        int value = (2 * i) + 1;
        if (value < target) {
            operations += (target - value) / 2;
        }
    }
    return operations;
}

