public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    int maxSum = 0;
    int minSum = 0;
    int currentMaxSum = 0;
    int currentMinSum = 0;

    for (int num : nums) {
        currentMaxSum = Math.max(num, currentMaxSum + num);
        currentMinSum = Math.min(num, currentMinSum + num);
        maxSum = Math.max(maxSum, currentMaxSum);
        minSum = Math.min(minSum, currentMinSum);
    }

    return Math.max(maxSum, -minSum);
}

public int maxAbsoluteSum(int[] nums) {
    int maxSum = 0;
    int minSum = 0;
    int result = 0;

    for (int num : nums) {
        maxSum = Math.max(num, maxSum + num);
        minSum = Math.min(num, minSum + num);
        result = Math.max(result, Math.max(maxSum, -minSum));
    }

    return result;
}

public int maxAbsoluteSum(int[] nums) {
    int maxSum = 0;
    int minSum = 0;
    int currentMaxSum = 0;
    int currentMinSum = 0;

    for (int num : nums) {
        currentMaxSum = Math.max(0, currentMaxSum + num);
        maxSum = Math.max(maxSum, currentMaxSum);

        currentMinSum = Math.min(0, currentMinSum - num);
        minSum = Math.min(minSum, currentMinSum);
    }

    return Math.max(maxSum, Math.abs(minSum));
