public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to or just below k
    List<Integer> fibNumbers = new ArrayList<>();
    int a = 1, b = 1;
    while (b <= k) {
        fibNumbers.add(b);
        int temp = b;
        b = a + b;
        a = temp;
    }

    // Use greedy algorithm to find the minimum number of Fibonacci numbers
    int count = 0;
    for (int i = fibNumbers.size() - 1; i >= 0; i--) {
        if (k >= fibNumbers.get(i)) {
            k -= fibNumbers.get(i);
            count++;
        }
        if (k == 0) {
            break;
        }
    }

    return count;
}

