public String makeGood(String s) {
    StringBuilder stack = new StringBuilder();
    for (char c : s.toCharArray()) {
        if (stack.length() > 0 && Math.abs(stack.charAt(stack.length() - 1) - c) == 32) {
            stack.deleteCharAt(stack.length() - 1);
        } else {
            stack.append(c);
        }
    }
    return stack.toString();
}

public String makeGood(String s) {
    StringBuilder stack = new StringBuilder();
    for (char c : s.toCharArray()) {
        if (stack.isEmpty()) {
            stack.append(c);
        } else {
            char last = stack.charAt(stack.length() - 1);
            if (Character.isUpperCase(last) && Character.toLowerCase(last) == c || 
                Character.isLowerCase(last) && Character.toUpperCase(last) == c) {
                stack.deleteCharAt(stack.length() - 1);
            } else {
                stack.append(c);
            }
        }
    }
    return stack.toString();
}

public String makeGood(String s) {
    StringBuilder stack = new StringBuilder();
    for (char c : s.toCharArray()) {
        if (stack.isEmpty() || !Character.isLetter(c) || Math.abs(stack.charAt(stack.length() - 1) - c) != 32) {
            stack.append(c);
        } else {
            stack.deleteCharAt(stack.length() - 1);
        }
    }
    return stack.toString();
}

public String makeGood(String s) {
    Deque<Character> stack = new ArrayDeque<>();

    for (char c : s.toCharArray()) {
        if (!stack.isEmpty() && Math.abs(stack.peek() - c) == 32) {
            stack.pop();
        } else {
            stack.push(c);
        }
    }

    StringBuilder result = new StringBuilder();
    while (!stack.isEmpty()) {
        result.append(stack.removeLast());
    }

    return result.toString();
}

public String makeGood(String s) {
    Stack<Character> stack = new Stack<>();

    for (char c : s.toCharArray()) {
        if (!stack.isEmpty() && Math.abs(stack.peek() - c) == 32) {
            stack.pop();
        } else {
            stack.push(c);
        }
    }

    StringBuilder result = new StringBuilder();
    for (char c : stack) {
        result.append(c);
    }

    return result.toString();
}

public int maxUniqueSplit(String s) {
    Set<String> seen = new HashSet<>();
    return backtrack(s, 0, seen);
}

private int backtrack(String s, int start, Set<String> seen) {
    if (start == s.length()) {
        return 0;
    }

    int maxUnique = 0;
    for (int end = start + 1; end <= s.length(); end++) {
        String substring = s.substring(start, end);
        if (seen.add(substring)) {
            maxUnique = Math.max(maxUnique, 1 + backtrack(s, end, seen));
            seen.remove(substring);
        }
    }

    return maxUnique;
}

