public String getSmallestString(int n, int k) {
        char[] result = new char[n];
        Arrays.fill(result, 'a');
        k -= n;

        for (int i = n - 1; i >= 0; i--) {
            if (k == 0) {
                break;
            }
            int add = Math.min(25, k);
            result[i] += add;
            k -= add;
        }

        return new String(result);
    }

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    Arrays.fill(result, 'a'); // Initialize the array with 'a'
    k -= n; // Subtract n because each 'a' contributes 1 to the sum

    while (k > 0) {
        int index = n - 1;
        while (index >= 0 && result[index] == 'z') {
            index--;
        }
        result[index]++;
        k--;
    }

    return new String(result);
}

