public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < n; i++) {
        int remainingValue = k - i;
        if (remainingValue <= 26) {
            result.append((char) ('a' + remainingValue - 1));
            k -= remainingValue;
        } else {
            result.append('z');
            k -= 26;
        }
    }
    return result.reverse().toString();
}

