public static int countDigitOne(int n) {
    if (n <= 0) return 0;

    int result = 0;
    long factor = 1;
    while (factor <= n) {
        long current = n / (factor * 10) * factor;
        long ahead = n % factor;
        long curDigit = (n / factor) % 10;

        if (curDigit == 0) {
            result += current;
        } else if (curDigit == 1) {
            result += current + ahead + 1;
        } else {
            result += current + factor;
        }

        factor *= 10;
    }

    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }

    int count = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long lowerNumbers = n - (n / factor) * factor;
        long currentDigit = (n / factor) % 10;
        long higherNumbers = n / (factor * 10);

        if (currentDigit == 0) {
            count += higherNumbers * factor;
        } else if (currentDigit == 1) {
            count += higherNumbers * factor + lowerNumbers + 1;
        } else {
            count += (higherNumbers + 1) * factor;
        }
    }

    return count;
}

