    int maxLength = 0;

    int[][][] dp = new int[5][rows][cols];

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 0) {
                continue;
            }
            dp[0][i][j] = dp[1][i][j] = dp[2][i][j] = dp[3][i][j] = 1;

            if (i > 0 && j > 0) {
                dp[2][i][j] += dp[2][i - 1][j - 1];
            }
            if (i > 0 && j < cols - 1) {
                dp[3][i][j] += dp[3][i - 1][j + 1];
            }
            if (i > 0) {
                dp[0][i][j] += dp[0][i - 1][j];
            }
            if (j > 0) {
                dp[1][i][j] += dp[1][i][j - 1];
            }

            maxLength = Math.max(maxLength, Math.max(dp[0][i][j], dp[1][i][j]));
            maxLength = Math.max(maxLength, Math.max(dp[2][i][j], dp[3][i][j]));
        }
    }

    return maxLength;
}

