        return "0";
    }

    String numberStr = String.valueOf(Math.abs(n));
    StringBuilder result = new StringBuilder();
    int length = numberStr.length();
    int count = 0;

    for (int i = length - 1; i >= 0; i--) {
        result.append(numberStr.charAt(i));
        count++;
        if (count == 3 && i != 0) {
            result.append('.');
            count = 0;
        }
    }

    return (n < 0) ? "-" + result.reverse().toString() : result.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    int count = 0;

    // Helper function to check if a number is a perfect square
    boolean isPerfectSquare(int num) {
        int sqrt = (int) Math.sqrt(num);
        return sqrt * sqrt == num;
    }

    // Helper function to check if a permutation is a square array
    boolean isSquareArray(int[] perm) {
        for (int i = 0; i < n - 1; i++) {
            if (!isPerfectSquare(perm[i] + perm[i + 1])) {
                return false;
            }
        }
        return true;
    }

    // Helper function to generate all permutations
    void permute(int[] perm, int index) {
        if (index == n) {
            if (isSquareArray(perm)) {
                count++;
            }
            return;
        }

        for (int i = index; i < n; i++) {
            swap(perm, index, i);
            permute(perm, index + 1);
            swap(perm, index, i); // backtrack
        }
    }

    // Helper function to swap elements in an array
    void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    // Main function to call the permutation generator
    permute(A.clone(), 0);

    return count;
}

