public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    return countSquarePermutations(A, 0, new Integer[A.length]);
}

private static int countSquarePermutations(int[] A, int start, Integer[] memo) {
    if (start == A.length - 1) {
        return 1;
    }

    if (memo[start] != null) {
        return memo[start];
    }

    int count = 0;
    for (int i = start + 1; i < A.length; i++) {
        int sum = A[start] + A[i];
        if (isPerfectSquare(sum)) {
            swap(A, start + 1, i);
            count += countSquarePermutations(A, start + 1, memo);
            swap(A, start + 1, i); // backtrack
        }
    }

    memo[start] = count;
    return count;
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

private static void swap(int[] A, int i, int j) {
    int temp = A[i];
    A[i] = A[j];
    A[j] = temp;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 1;
    if (n == 1) return 1;

    return countSquarePermutations(A, 1, A[0]);
}

private static int countSquarePermutations(int[] A, int currentIndex, int lastElement) {
    if (currentIndex == A.length) return 1;

    int count = 0;
    for (int i = currentIndex; i < A.length; i++) {
        if (isPerfectSquare(lastElement + A[i])) {
            count += countSquarePermutations(A, currentIndex + 1, A[i]);
        }
    }

    return count;
}

private static boolean isPerfectSquare(int num) {
    if (num < 0) return false;
    int root = (int) Math.sqrt(num);
    return root * root == num;
}

public static int squarePermutations(int[] A) {
    int N = A.length;
    boolean[][] dp = new boolean[N][N!];
    dp[0][0] = true;

    ArrayList<Integer>[] adj = new ArrayList[N];
    for (int i = 0; i < N; i++) {
        adj[i] = new ArrayList<>();
    }

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            int sum = A[i] + A[j];
            int root = (int) Math.sqrt(sum);
            if (root * root == sum) {
                adj[i].add(j);
                adj[j].add(i);
            }
        }
    }

    int[] factorial = new int[N + 1];
    factorial[0] = 1;
    for (int i = 1; i <= N; i++) {
        factorial[i] = factorial[i - 1] * i;
    }

    int result = 0;
    for (int mask = 0; mask < N!; mask++) {
        if (dp[0][mask]) {
            result += dfs(adj, dp, new boolean[N], mask, 0);
        }
    }

    return result;
}

private static int dfs(ArrayList<Integer>[] adj, boolean[][] dp, boolean[] used, int mask, int u) {
    if (u == adj.length - 1) {
        return 1;
    }

    int result = 0;
    for (int v : adj[u]) {
        int bit = 1 << (v * 2);
        if ((mask & bit) == 0) {
            dp[v][(mask & (bit ^ 0xfd)) | (1 << (v * 2 + 1))] = true;
            if (!used[v]) {
                used[v] = true;
                result += dfs(adj, dp, used, (mask & (bit ^ 0xfd)) | (1 << (v * 2 + 1)), v);
                used[v] = false;
            }
        }
    }

    return result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) {
        return 0;
    }

    int[] count = new int[n];
    for (int num : A) {
        count[num]++;
    }

    int result = 0;
    for (int i = 0; i < n; i++) {
        if (count[A[i]] == 0) continue;
        count[A[i]]--;

        boolean[] visited = new boolean[n];
        visited[i] = true;

        int current = A[i];
        for (int j = 0; j < n; j++) {
            if (!visited[j] && (int) Math.sqrt(current + A[j]) == Math.sqrt(current + A[j])) {
                visited[j] = true;
                if (j == n - 1) {
                    result++;
                } else {
                    boolean found = false;
                    for (int k = j + 1; k < n; k++) {
                        if (!visited[k] && (int) Math.sqrt(A[j] + A[k]) == Math.sqrt(A[j] + A[k])) {
                            found = true;
                            break;
                        }
                    }
                    if (!found) {
                        break;
                    }
                }
            }
        }

        visited[i] = false;
        count[A[i]]++;
    }

    return result;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    Stack<Integer> stack = new Stack<>();
    int maxArea = 0;
    int index = 0;

    while (index < heights.length) {
        if (stack.isEmpty() || heights[index] >= heights[stack.peek()]) {
            stack.push(index++);
        } else {
            int topOfStack = stack.pop();
            int area = heights[topOfStack] * (stack.isEmpty() ? index : index - stack.peek() - 1);
            maxArea = Math.max(maxArea, area);
        }
    }

    while (!stack.isEmpty()) {
        int topOfStack = stack.pop();
        int area = heights[topOfStack] * (stack.isEmpty() ? index : index - stack.peek() - 1);
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    int n = heights.length;

    for (int i = 0; i < n; i++) {
        int minHeight = Integer.MAX_VALUE;

        for (int j = i; j >= 0; j--) {
            minHeight = Math.min(minHeight, heights[j]);
            int width = i - j + 1;
            int area = minHeight * width;
            maxArea = Math.max(maxArea, area);
        }
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
        if (heights == null || heights.length == 0) {
            return 0;
        }

        int n = heights.length;
        Stack<Integer> stack = new Stack<>();
        int maxArea = 0;

        for (int i = 0; i <= n; i++) {
            int currentHeight = (i == n) ? 0 : heights[i];
            while (!stack.isEmpty() && heights[stack.peek()] > currentHeight) {
                int height = heights[stack.pop()];
                int width = stack.isEmpty() ? i : i - stack.peek() - 1;
                maxArea = Math.max(maxArea, height * width);
            }
            stack.push(i);
        }

        return maxArea;
    }

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int[] stack = new int[heights.length];
    int top = -1;

    for (int i = 0; i <= heights.length; i++) {
        int currentHeight = (i == heights.length) ? 0 : heights[i];

        while (top != -1 && currentHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            maxArea = Math.max(maxArea, height * width);
        }

        stack[++top] = i;
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0)
        return 0;

    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    Stack<Integer> stack = new Stack<>();

    // Fill left[] array
    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i])
            stack.pop();
        left[i] = stack.isEmpty() ? 0 : stack.peek() + 1;
        stack.push(i);
    }

    // Clear stack for reuse
    stack.clear();

    // Fill right[] array
    for (int i = n - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i])
            stack.pop();
        right[i] = stack.isEmpty() ? n - 1 : stack.peek() - 1;
        stack.push(i);
    }

    // Calculate the maximum area
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        int area = heights[i] * (right[i] - left[i] + 1);
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
