            result.add(new String(array));
            array[left] = '9';
            array[right] = '6';
            result.add(new String(array));
            return;
        }
        char[] choices = {'0', '1', '6', '8', '9'};
        for (char choice : choices) {
            array[left] = choice;
            array[right] = getMirror(choice);
            centerSymmetricNumbersHelper(n, array, left + 1, right - 1, result);
