public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate the area of the triangle formed by the points
    int area = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);

    // The points form a boomerang if the area is not zero
    return area != 0;
}

public static boolean isBoomerang(int[][] points) {
    // Check if any two points are the same
    if (points[0][0] == points[1][0] && points[0][1] == points[1][1] ||
        points[0][0] == points[2][0] && points[0][1] == points[2][1] ||
        points[1][0] == points[2][0] && points[1][1] == points[2][1]) {
        return false;
    }

    // Calculate the area of the triangle using the determinant method
    int area = points[0][0] * (points[1][1] - points[2][1]) +
               points[1][0] * (points[2][1] - points[0][1]) +
               points[2][0] * (points[0][1] - points[1][1]);

    // If the area is zero, the points are collinear and do not form a boomerang
    return area != 0;
}

