public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueElements = new HashSet<>();
    Set<Integer> duplicates = new HashSet<>();
    int sum = 0;
    for (int num : nums) {
        if (!uniqueElements.add(num)) {
            duplicates.add(num);
        }
    }
    for (int num : nums) {
        if (!duplicates.contains(num)) {
            sum += num;
        }
    }
    return sum;
}

public static int calculateUniqueSum(int[] nums) {
    int sum = 0;
    Map<Integer, Integer> countMap = new HashMap<>();

    // Count the occurrences of each number
    for (int num : nums) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }

    // Sum the numbers that appear exactly once
    for (Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }

    return sum;
}

public static int minPerfectSquareSum(int n) {
    // Create an array to store the minimum number of perfect squares for each number up to n
    int[] dp = new int[n + 1];

    // Base case: The minimum number of perfect squares to sum up to 0 is 0
    dp[0] = 0;

    // Fill the dp array for each number from 1 to n
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // Initialize with the maximum possible (i.e., i == 1 + 1 + ... + 1)
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    // The answer for n will be stored in dp[n]
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // Maximum number of 1's needed, which is i itself
    }

    for (int i = 2; i * i <= n; i++) {
        for (int j = i * i; j <= n; j++) {
            dp[j] = Math.min(dp[j], dp[j - i * i] + 1);
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    // Array to store the minimum number of squares for all numbers up to n
    int[] dp = new int[n + 1];

    // Base cases
    dp[0] = 0; // 0 can be represented by 0 squares
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // Initialize with the worst case (i squares of 1)
    }

    // Fill the dp array
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

